SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS `daily_spoken_dialogue_item` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `lesson_code` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `chapter_title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `lesson_title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `lesson_order` int NOT NULL DEFAULT '0',
  `section_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `section_title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `section_order` int NOT NULL DEFAULT '0',
  `item_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `item_order` int NOT NULL,
  `speaker` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `item_title` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `english_text` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `chinese_text` longtext COLLATE utf8mb4_unicode_ci,
  `pronunciation` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `explanation` longtext COLLATE utf8mb4_unicode_ci,
  `examples` longtext COLLATE utf8mb4_unicode_ci,
  `keywords` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_published` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_daily_dialogue_lesson_item` (`lesson_code`,`item_order`),
  KEY `idx_daily_dialogue_lesson_section` (`lesson_code`,`is_published`,`section_order`,`item_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='日常口语对话学习内容表';

