    ('buying-clothes', 'Chapter 1 · Shopping', 'Lesson 1 · Buying Clothes', 1, 'extra', '拓展服饰词汇', 6, 'extra', 504, NULL, 'mountain parka', 'mountain parka', '冲锋衣', NULL, 'A warm jacket with a hood, often used outdoors.', NULL, 'mountain parka, jacket', 1),
    ('buying-clothes', 'Chapter 1 · Shopping', 'Lesson 1 · Buying Clothes', 1, 'extra', '拓展服饰词汇', 6, 'extra', 505, NULL, 'Hawaiian shirt', 'Hawaiian shirt', '夏威夷衬衫', NULL, 'A colourful short-sleeved shirt with a tropical print.', NULL, 'Hawaiian shirt, shirt', 1),
    ('buying-clothes', 'Chapter 1 · Shopping', 'Lesson 1 · Buying Clothes', 1, 'extra', '拓展服饰词汇', 6, 'extra', 506, NULL, 'culottes', 'culottes', '女裙裤', NULL, 'Wide-legged trousers that look like a skirt.', NULL, 'culottes, trousers, fashion', 1),
    ('choosing-a-gift', 'Chapter 1 · Shopping', 'Lesson 2 · Choosing a Gift', 2, 'vocabulary', '核心词汇', 1, 'vocabulary', 1, NULL, 'look for', 'look for', '寻找（某物或某人）', '/lʊk fɔːr/', 'to try to find something or someone', 'They''re looking for insects in the field.', 'look for, gift', 1),
    ('choosing-a-gift', 'Chapter 1 · Shopping', 'Lesson 2 · Choosing a Gift', 2, 'vocabulary', '核心词汇', 1, 'vocabulary', 2, NULL, 'have ... in mind', 'have something in mind', '心里有想法；想起某件事', NULL, 'to think of something', 'What do you have in mind?', 'have in mind, idea', 1),
    ('choosing-a-gift', 'Chapter 1 · Shopping', 'Lesson 2 · Choosing a Gift', 2, 'vocabulary', '核心词汇', 1, 'vocabulary', 3, NULL, 'how about (doing) something', 'how about (doing) something', '……怎么样？', NULL, 'used to introduce a relevant new suggestion or subject', 'How about a cup of coffee? How about going to the cinema?', 'how about, suggestion', 1),
