    ('choosing-a-gift', 'Chapter 1 · Shopping', 'Lesson 2 · Choosing a Gift', 2, 'dialogue', '示范对话', 2, 'dialogue', 101, 'Salesman', NULL, 'Good evening, sir, can I help you?', '晚上好，先生，需要帮忙吗？', NULL, NULL, NULL, 'can I help you', 1),
    ('choosing-a-gift', 'Chapter 1 · Shopping', 'Lesson 2 · Choosing a Gift', 2, 'dialogue', '示范对话', 2, 'dialogue', 102, 'Mark', NULL, 'Yeah! I''m looking for a gift for my girlfriend.', '是的！我在给女朋友挑礼物。', NULL, NULL, NULL, 'look for, gift', 1),
    ('choosing-a-gift', 'Chapter 1 · Shopping', 'Lesson 2 · Choosing a Gift', 2, 'dialogue', '示范对话', 2, 'dialogue', 103, 'Salesman', NULL, 'Do you have something in mind?', '您心里有想要的吗？', NULL, NULL, NULL, 'have something in mind', 1),
    ('choosing-a-gift', 'Chapter 1 · Shopping', 'Lesson 2 · Choosing a Gift', 2, 'dialogue', '示范对话', 2, 'dialogue', 104, 'Mark', NULL, 'I think a necklace would be perfect.', '我想一条项链会很合适。', NULL, NULL, NULL, 'necklace', 1),
    ('choosing-a-gift', 'Chapter 1 · Shopping', 'Lesson 2 · Choosing a Gift', 2, 'dialogue', '示范对话', 2, 'dialogue', 105, 'Salesman', NULL, 'How about this one? It sells very well.', '这个怎么样？卖得很好。', NULL, NULL, NULL, 'how about, sell well', 1),
    ('choosing-a-gift', 'Chapter 1 · Shopping', 'Lesson 2 · Choosing a Gift', 2, 'dialogue', '示范对话', 2, 'dialogue', 106, 'Mark', NULL, 'Sounds good, but could you gift-wrap this, please?', '听起来不错，不过可以帮我包装成礼物吗？', NULL, NULL, NULL, 'gift-wrap', 1),
