    ('choosing-a-gift', 'Chapter 1 · Shopping', 'Lesson 2 · Choosing a Gift', 2, 'practice', '情景补全对话', 3, 'practice', 201, 'A', NULL, 'Can I help you, sir/madam?', '先生／女士，需要帮忙吗？', NULL, NULL, NULL, 'gift, practice', 1),
    ('choosing-a-gift', 'Chapter 1 · Shopping', 'Lesson 2 · Choosing a Gift', 2, 'practice', '情景补全对话', 3, 'practice', 202, 'B', NULL, 'Yes, I''m looking for a gift for my mother, but I don''t have anything in mind.', '是的，我在给妈妈挑礼物，但心里还没有想法。', NULL, NULL, NULL, 'look for, have in mind', 1),
    ('choosing-a-gift', 'Chapter 1 · Shopping', 'Lesson 2 · Choosing a Gift', 2, 'practice', '情景补全对话', 3, 'practice', 203, 'A', NULL, 'How about this necklace? It''s beautiful and perfect as a gift.', '这条项链怎么样？它很漂亮，很适合作为礼物。', NULL, NULL, NULL, 'how about, necklace', 1),
    ('choosing-a-gift', 'Chapter 1 · Shopping', 'Lesson 2 · Choosing a Gift', 2, 'practice', '情景补全对话', 3, 'practice', 204, 'B', NULL, 'Could you gift-wrap this?', '可以帮我包装成礼物吗？', NULL, NULL, NULL, 'gift-wrap', 1),
    ('choosing-a-gift', 'Chapter 1 · Shopping', 'Lesson 2 · Choosing a Gift', 2, 'practice', '情景补全对话', 3, 'practice', 205, 'A', NULL, 'Sure. We offer free gift wrapping.', '当然可以。我们提供免费礼品包装。', NULL, NULL, NULL, 'gift wrapping', 1),
    ('choosing-a-gift', 'Chapter 1 · Shopping', 'Lesson 2 · Choosing a Gift', 2, 'practice', '情景补全对话', 3, 'practice', 206, 'B', NULL, 'That''s great. I''ll take it.', '太好了，我买了。', NULL, NULL, NULL, 'take it', 1),
    ('choosing-a-gift', 'Chapter 1 · Shopping', 'Lesson 2 · Choosing a Gift', 2, 'discussion', '开口讨论', 4, 'discussion', 301, NULL, 'Describe a gift that you sent to someone recently or in the past.', 'Describe a gift that you sent to someone recently or in the past.', '描述你最近或过去送给别人的一件礼物。', NULL, 'What was the gift? Who did you send it to? When did you send it?', NULL, 'gift, describe', 1),
    ('choosing-a-gift', 'Chapter 1 · Shopping', 'Lesson 2 · Choosing a Gift', 2, 'discussion', '开口讨论', 4, 'discussion', 302, NULL, 'Describe a gift that you received.', 'Describe a gift that you received.', '描述你收到过的一件礼物。', NULL, 'What was the gift? Who gave it to you? When did you receive it? Did you like it? Why or why not?', NULL, 'receive a gift', 1),
    ('choosing-a-gift', 'Chapter 1 · Shopping', 'Lesson 2 · Choosing a Gift', 2, 'discussion', '开口讨论', 4, 'discussion', 303, NULL, 'Do you think gifts should be wrapped? Why or why not?', 'Do you think gifts should be wrapped? Why or why not?', '你认为礼物应该包装吗？为什么？', NULL, 'Yes: more beautiful and gives somebody a surprise. No: it can be useless or a waste of paper.', NULL, 'gift wrap, opinion', 1),
    ('choosing-a-gift', 'Chapter 1 · Shopping', 'Lesson 2 · Choosing a Gift', 2, 'review', '复习表达', 5, 'review', 401, NULL, 'Key expressions', 'How about this one? Could you gift-wrap this, please?', '复习：look for / have something in mind / how about (doing) something / gift-wrap。', NULL, NULL, NULL, 'review, gift', 1),
