    ('in-the-supermarket', 'Chapter 1 · Shopping', 'Lesson 3 · In the Supermarket', 3, 'practice', '情景补全对话', 3, 'practice', 203, 'A', NULL, 'Thanks.', '谢谢。', NULL, NULL, NULL, 'thanks', 1),
    ('in-the-supermarket', 'Chapter 1 · Shopping', 'Lesson 3 · In the Supermarket', 3, 'practice', '情景补全对话', 3, 'practice', 204, 'B', NULL, 'Have a look at this pack. It''s being promoted and it is selling well.', '看看这个礼包。它正在促销，而且卖得很好。', NULL, NULL, NULL, 'promoted, pack', 1),
    ('in-the-supermarket', 'Chapter 1 · Shopping', 'Lesson 3 · In the Supermarket', 3, 'practice', '情景补全对话', 3, 'practice', 205, 'A', NULL, 'What''s included in the pack?', '礼包里包括什么？', NULL, NULL, NULL, 'included, pack', 1),
    ('in-the-supermarket', 'Chapter 1 · Shopping', 'Lesson 3 · In the Supermarket', 3, 'practice', '情景补全对话', 3, 'practice', 206, 'B', NULL, 'Toothbrushes, toothpaste and mouthwash. They''re only 25 yuan in total.', '牙刷、牙膏和漱口水，总共只要 25 元。', NULL, NULL, NULL, 'toothbrushes, toothpaste, mouthwash', 1),
    ('in-the-supermarket', 'Chapter 1 · Shopping', 'Lesson 3 · In the Supermarket', 3, 'practice', '情景补全对话', 3, 'practice', 207, 'A', NULL, 'It''s a good deal.', '这很划算。', NULL, NULL, NULL, 'good deal', 1),
    ('in-the-supermarket', 'Chapter 1 · Shopping', 'Lesson 3 · In the Supermarket', 3, 'discussion', '开口讨论', 4, 'discussion', 301, NULL, 'When are things in the supermarket promoted in your city? Will you buy a lot when they are being promoted? Why?', 'When are things in the supermarket promoted in your city? Will you buy a lot when they are being promoted? Why?', '你所在城市的超市通常何时促销？促销时你会大量购买吗？为什么？', NULL, 'Think about holidays such as Christmas or Women''s Day; low price, good deal, or waste. ', NULL, 'promotion, supermarket', 1),
    ('in-the-supermarket', 'Chapter 1 · Shopping', 'Lesson 3 · In the Supermarket', 3, 'discussion', '开口讨论', 4, 'discussion', 302, NULL, 'How often do you go to the supermarket? What do you usually buy there?', 'How often do you go to the supermarket? What do you usually buy there?', '你多久去一次超市？通常买什么？', NULL, 'every day / every week / when needed / once in a while; bread / fruit / drinks / shower gel.', NULL, 'supermarket, frequency', 1),
    ('in-the-supermarket', 'Chapter 1 · Shopping', 'Lesson 3 · In the Supermarket', 3, 'discussion', '开口讨论', 4, 'discussion', 303, NULL, 'Have you ever bought things in an online supermarket? Do you like it? Why or why not?', 'Have you ever bought things in an online supermarket? Do you like it? Why or why not?', '你在网上超市买过东西吗？喜欢吗？为什么？', NULL, 'It is convenient and avoids carrying heavy bags, but delivery can take days.', NULL, 'online supermarket, delivery', 1),
