    ('shopping-for-a-tv', 'Chapter 1 · Shopping', 'Lesson 4 · Shopping for a TV', 4, 'practice', '情景补全对话', 3, 'practice', 202, 'B', NULL, 'Three years. It''s the best-seller now. We also offer free delivery.', '三年。它现在是热卖款，我们还提供免费送货。', NULL, NULL, NULL, 'best-seller, free delivery', 1),
    ('shopping-for-a-tv', 'Chapter 1 · Shopping', 'Lesson 4 · Shopping for a TV', 4, 'practice', '情景补全对话', 3, 'practice', 203, 'A', NULL, 'But there''s an air conditioner of this brand in my living room, and it doesn''t work very well recently.', '但我家客厅有一台这个品牌的空调，最近不太好用。', NULL, NULL, NULL, 'brand, work well', 1),
    ('shopping-for-a-tv', 'Chapter 1 · Shopping', 'Lesson 4 · Shopping for a TV', 4, 'practice', '情景补全对话', 3, 'practice', 204, 'B', NULL, 'We''ll offer free repair if it''s still under warranty.', '如果还在保修期内，我们会提供免费维修。', NULL, NULL, NULL, 'free repair, warranty', 1),
