    ('online-shopping', 'Chapter 1 · Shopping', 'Lesson 9 · Online Shopping', 9, 'dialogue', '示范对话', 2, 'dialogue', 101, 'Anna', NULL, 'Hey, where did you buy this dress?', '嘿，你在哪里买的这条裙子？', NULL, NULL, NULL, 'buy, dress', 1),
